def escape(s: t.Any, /) -> Markup:
    if hasattr(s, "__html__"):
        s = s.__html__()

    s = str(s)
    s = s.replace("&", "&amp;")
    s = s.replace("<", "&lt;")
    s = s.replace(">", "&gt;")
    s = s.replace('"', "&#34;")
    s = s.replace("'", "&#39;")
    return Markup(s)


def escape_silent(s: (t.Any | None), /) -> Markup:
    if s is None:
        return Markup()

    if hasattr(s, "__html__"):
        s = s.__html__()

    s = str(s)
    s = s.replace("&", "&amp;")
    s = s.replace("<", "&lt;")
    s = s.replace(">", "&gt;")
    s = s.replace('"', "&#34;")
    s = s.replace("'", "&#39;")
    return Markup(s)
